String _s(Object? v) => v?.toString() ?? '0'; DateTime? _d(Object? v) => v is String ? DateTime.tryParse(v) : null;
PartBid bidFromJson(Map<String, dynamic> j) => PartBid(id: j['id'] as String, supplierOrgId: j['supplierOrgId'] as String, condition: j['condition'] as String, unitPrice: _s(j['unitPrice']), quantity: (j['quantity'] as num).toInt(), deliveryFee: _s(j['deliveryFee']), etaHours: (j['deliveryEtaHours'] as num?)?.toInt(), warrantyDays: (j['warrantyDays'] as num?)?.toInt() ?? 0, notesAr: j['notesAr'] as String?, status: j['status'] as String, createdAt: DateTime.parse(j['createdAt'] as String), whereText: (j['where_text'] ?? j['whereText']) as String?, distanceKm: (j['distance_km'] ?? j['distanceKm'])?.toString(),
    mediaIds: [for (final m in (j['media_ids'] ?? j['mediaIds'] ?? const []) as List) m as String]);
PartRequest requestFromJson(Map<String, dynamic> j) => PartRequest(id: j['id'] as String, number: j['number'] as String, partNameAr: j['partNameAr'] as String, vin: j['vin'] as String?, descriptionAr: j['descriptionAr'] as String?, acceptedConditions: ((j['acceptedConditions'] as List?) ?? []).cast<String>(), quantity: (j['quantity'] as num?)?.toInt() ?? 1, biddingEndsAt: DateTime.parse(j['biddingEndsAt'] as String), status: j['status'] as String, awardedBidId: j['awardedBidId'] as String?, bidsCount: (j['bids_count'] as num?)?.toInt() ?? ((j['bids'] as List?)?.length ?? 0), lowestBid: j['lowest_bid']?.toString(), bids: ((j['bids'] as List?) ?? []).cast<Map<String, dynamic>>().map(bidFromJson).toList(), requesterOrgId: j['requesterOrgId'] as String?, createdAt: DateTime.parse(j['createdAt'] as String));
PartOrder orderFromJson(Map<String, dynamic> j) => PartOrder(id: j['id'] as String, number: j['number'] as String, source: j['source'] as String, status: j['status'] as String, paymentTerms: j['paymentTerms'] as String, supplierOrgId: j['supplierOrgId'] as String, buyerOrgId: j['buyerOrgId'] as String?, buyerUserId: j['buyerUserId'] as String?, workOrderId: j['workOrderId'] as String?, total: _s(j['total']), deliveredAt: _d(j['deliveredAt']), autoConfirmAt: _d(j['autoConfirmAt']), createdAt: DateTime.parse(j['createdAt'] as String), invoiceId: j['invoice_id'] as String?, items: ((j['items'] as List?) ?? []).cast<Map<String, dynamic>>().map((i) => PartOrderItem(descriptionAr: i['descriptionAr'] as String, condition: i['condition'] as String, quantity: (i['quantity'] as num).toInt(), unitPrice: _s(i['unitPrice']), lineTotal: _s(i['lineTotal']), warrantyDays: (i['warrantyDays'] as num?)?.toInt() ?? 0)).toList());
TradeAccount taFromJson(Map<String, dynamic> j) => TradeAccount(id: j['id'] as String, sellerOrgId: j['sellerOrgId'] as String, buyerOrgId: j['buyerOrgId'] as String, status: j['status'] as String, creditLimit: _s(j['creditLimit']), outstanding: _s(j['outstanding']), available: j['available']?.toString() ?? ((double.tryParse(_s(j['creditLimit'])) ?? 0) - (double.tryParse(_s(j['outstanding'])) ?? 0)).toStringAsFixed(2), paymentTermsDays: (j['paymentTermsDays'] as num?)?.toInt() ?? 30, discountBps: (j['discountBps'] as num?)?.toInt() ?? 0, counterpartyAr: j['counterparty_ar'] as String?);
