class PartsRepositoryImpl implements PartsRepository {
  final ApiClient api; PartsRepositoryImpl(this.api);
  Future<Result<T>> _run<T>(Future<T> Function() f) async { try { return Result.ok(await f()); } catch (e) { return Result.err(mapDioError(e)); } }
  @override Future<Result<FitResult>> fit({String? vin, String? vehicleId, String? categoryCode, String? text, String? buyerOrgId}) => _run(() async { final d = (await api.dio.get<Map<String, dynamic>>('/parts/fit', queryParameters: {'vin': ?vin, 'vehicle_id': ?vehicleId, 'category_code': ?categoryCode, 'q': ?text, 'buyer_org_id': ?buyerOrgId})).data!; final v = (d['vehicle'] as Map?) ?? {}; return FitResult(make: v['make'] as String?, model: v['model'] as String?, year: (v['year'] as num?)?.toInt(), offers: ((d['offers'] as List?) ?? []).cast<Map<String, dynamic>>().map((o) => PartOffer(inventoryId: o['inventory_id'] as String, supplierOrgId: o['supplier_org_id'] as String, supplierNameAr: o['supplier_name_ar'] as String?, titleAr: o['title_ar'] as String, partNumber: o['part_number'] as String?, brandAr: o['brand_ar'] as String?, condition: o['condition'] as String, price: o['price']?.toString(), tradePrice: o['trade_price']?.toString(), tradeAccountId: o['trade_account_id'] as String?, quantity: (o['quantity'] as num).toInt(), warrantyDays: (o['warranty_days'] as num?)?.toInt() ?? 0, leadTimeHours: (o['lead_time_hours'] as num?)?.toInt(), isSerialized: o['is_serialized'] as bool? ?? false, fitmentSource: (o['fitment_source'] ?? 'listing') as String, whereText: o['where_text'] as String?)).toList()); });
  @override Future<Result<PartOrder>> buyNow({String? orgId, String? workOrderId, required String paymentTerms, required List<({String inventoryId, int quantity})> items}) => _run(() async => orderFromJson((await api.dio.post<Map<String, dynamic>>('/parts/orders/buy-now', data: {'org_id': ?orgId, 'work_order_id': ?workOrderId, 'payment_terms': paymentTerms, 'items': items.map((i) => {'inventory_id': i.inventoryId, 'quantity': i.quantity}).toList()})).data!));
  @override Future<Result<PartRequest>> createRequest({String? orgId, String? workOrderId, String? vin, required String partNameAr, String? descriptionAr, List<String>? acceptedConditions, int quantity = 1, int? biddingMinutes}) => _run(() async => requestFromJson((await api.dio.post<Map<String, dynamic>>('/parts/requests', data: {'org_id': ?orgId, 'work_order_id': ?workOrderId, 'vin': ?vin, 'part_name_ar': partNameAr, 'description_ar': ?descriptionAr, 'accepted_conditions': ?acceptedConditions, 'quantity': quantity, 'bidding_minutes': ?biddingMinutes})).data!));
  @override Future<Result<List<PartRequest>>> myRequests({String? orgId, bool asSupplier = false}) => _run(() async => (await api.dio.get<List<dynamic>>('/parts/requests', queryParameters: {'org_id': ?orgId, if (asSupplier) 'as': 'supplier'})).data!.cast<Map<String, dynamic>>().map(requestFromJson).toList());
  @override Future<Result<PartRequest>> request(String id) => _run(() async => requestFromJson((await api.dio.get<Map<String, dynamic>>('/parts/requests/$id')).data!));
  @override Future<Result<PartOrder>> accept(String requestId, String bidId, {String paymentTerms = 'prepaid'}) => _run(() async => orderFromJson(((await api.dio.post<Map<String, dynamic>>('/parts/requests/$requestId/accept', data: {'bid_id': bidId, 'payment_terms': paymentTerms})).data!['order']) as Map<String, dynamic>));
  @override Future<Result<List<PartOrder>>> orders({String? orgId, bool asSupplier = false}) => _run(() async => (await api.dio.get<List<dynamic>>('/parts/orders', queryParameters: {'org_id': ?orgId, if (asSupplier) 'as': 'supplier'})).data!.cast<Map<String, dynamic>>().map(orderFromJson).toList());
  @override Future<Result<PartOrder>> order(String id) => _run(() async => orderFromJson((await api.dio.get<Map<String, dynamic>>('/parts/orders/$id')).data!));
  @override Future<Result<void>> requestDelivery(String orderId) => _run(() async => (await api.dio.post<Map<String, dynamic>>('/parts/orders/$orderId/delivery', data: const <String, dynamic>{})).data);
  @override Future<Result<void>> confirm(String orderId) => _run(() async { await api.dio.post<void>('/parts/orders/$orderId/confirm'); });
  @override Future<Result<List<TradeAccount>>> tradeAccounts({required String orgId, required bool asSeller}) => _run(() async => (await api.dio.get<List<dynamic>>('/parts/trade-accounts', queryParameters: {'org_id': orgId, 'as': asSeller ? 'seller' : 'buyer'})).data!.cast<Map<String, dynamic>>().map(taFromJson).toList());
  @override Future<Result<TradeAccount>> requestTradeAccount({required String sellerOrgId, required String buyerOrgId}) => _run(() async => taFromJson((await api.dio.post<Map<String, dynamic>>('/parts/trade-accounts', data: {'seller_org_id': sellerOrgId, 'buyer_org_id': buyerOrgId})).data!));
  @override Future<Result<TradeAccount>> approveTradeAccount(String id, {required String creditLimit, int termsDays = 30, int discountBps = 0}) => _run(() async => taFromJson((await api.dio.post<Map<String, dynamic>>('/parts/trade-accounts/$id/approve', data: {'credit_limit': creditLimit, 'payment_terms_days': termsDays, 'discount_bps': discountBps})).data!));
  @override Future<Result<SerialVerify>> verify(String qrToken) => _run(() async { final d = (await api.dio.get<Map<String, dynamic>>('/parts/verify/$qrToken', options: null)).data!; final p = d['part'] as Map?; return SerialVerify(genuine: d['genuine'] as bool, alert: d['alert'] as bool? ?? false, status: d['status'] as String?, serialNumber: d['serial_number'] as String?, partNameAr: p?['name_ar'] as String?, partNumber: p?['part_number'] as String?, brandAr: p?['brand_ar'] as String?, issuerAr: d['issuer_ar'] as String?, messageAr: d['message_ar'] as String, messageEn: d['message_en'] as String); });
  @override Future<Result<Warranty>> install({required String qrToken, required String workOrderItemId, int laborWarrantyDays = 180}) => _run(() async => warrantyFromJson((await api.dio.post<Map<String, dynamic>>('/parts/serials/install', data: {'qr_token': qrToken, 'work_order_item_id': workOrderItemId, 'labor_warranty_days': laborWarrantyDays})).data!['warranty'] as Map<String, dynamic>));
