  @override Future<Result<PartBid>> bid(String requestId, {required String orgId, required String condition, required String unitPrice, int quantity = 1, String deliveryFee = '0', int? etaHours, int warrantyDays = 0, String? notesAr, List<String> mediaIds = const []}) => _run(() async => bidFromJson((await api.dio.post<Map<String, dynamic>>('/parts/requests/$requestId/bids', data: {'org_id': orgId, 'condition': condition, 'unit_price': unitPrice, 'quantity': quantity, 'delivery_fee': deliveryFee, 'delivery_eta_hours': ?etaHours, 'warranty_days': warrantyDays, 'notes_ar': ?notesAr, 'media_ids': mediaIds})).data!));
