  @override Future<Result<List<InventoryItem>>> inventory(String orgId) => _run(() async => (await api.dio.get<List<dynamic>>('/parts/orgs/$orgId/inventory')).data!.cast<Map<String, dynamic>>().map((i) => InventoryItem(id: i['id'] as String, titleAr: i['titleAr'] as String, partNumber: i['partNumber'] as String?, condition: i['condition'] as String, price: i['price']?.toString(), tradePrice: i['tradePrice']?.toString(), quantity: (i['quantity'] as num).toInt(), reservedQty: (i['reservedQty'] as num?)?.toInt() ?? 0, externalSku: i['externalSku'] as String?)).toList());
